                if kind == RKind::ApplyPatch {
                    it.text = "x".to_owned();
                }
                if matches!(q, RQuirk::FailedWithOpenItem | RQuirk::EofInItem) {
                    self.items.push(it);
                } else {
                    let pos = at % (self.items.len() + 1);
                    self.items.insert(pos, it);
                }
            }
        }
    }
